#!/usr/bin/env python3
from __future__ import annotations
import html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; DATA=ROOT/'data'; SITE=ROOT/'site'; BASE='/dc-public-realm'
def load(n): return json.loads((DATA/n).read_text(encoding='utf-8'))
def esc(x): return html.escape(str(x))
E={x['entity_id']:x for x in load('entities.json')['entities']}; A={x['assertion_id']:x for x in load('assertions.json')['assertions']}; S={x['source_id']:x for x in load('sources.json')['sources']}; evidence=load('assertion-evidence.json')['assertion_evidence']; tasks=[x for x in load('research-tasks.json')['tasks'] if x.get('object_entity_id')=='OBJ-0001']; MODES={x['assertion_id']:x['mode'] for x in load('claim-modes.json')['claim_modes']}; MODE_LABEL={'DOCUMENTARY_FACT':'Historical record','ATTRIBUTION_RECONSTRUCTION':'Attribution','INTERPRETATION':'Interpretation'}; EV={}
for e in evidence: EV.setdefault(e['assertion_id'],[]).append(e)
ROLE={'PRIMARY_SUPPORT':'Main source','CORROBORATION':'Additional source','QUALIFIES':'Qualification','CONTRADICTS':'Contradictory source','IMAGE_EVIDENCE':'Image evidence'}
CLAIMS=[('A-0001','Gift to the United States','Congressional records describe the memorial as a gift from the people of Uruguay.'),('A-0002','Current custody','The National Park Service is recorded as the current custodian.'),('A-0004','Relationship to the earlier monument','Uruguay’s heritage record identifies the Washington bronze as a copy of the 1898 Artigas monument at San José de Mayo. A Smithsonian inventory instead calls the Washington work a recast while locating its predecessor in Montevideo, so the exact physical-object relationship remains contested.'),('A-0005','Casting location','A Smithsonian inventory associates the Washington recast with Montevideo, Uruguay. The present evidence does not establish the foundry.'),('A-0005B','Approximate recast date','The Smithsonian inventory dates the Washington recast approximately to the early 1940s.')]
def slink(s): return f'<a href="{esc(s["url"])}">{esc(s["title"])}</a>'
def evidence_label(evs):
 pubs={e.get('source_id') for e in evs if e.get('source_id')}; n=len(pubs)
 if any(e.get('evidence_role')=='CONTRADICTS' for e in evs): return f'{n} publications · sources conflict'
 pos=[e for e in evs if e.get('evidence_role') in {'PRIMARY_SUPPORT','CORROBORATION','IMAGE_EVIDENCE'}]
 if len(pos)>1 and any(e.get('claim_origin')=='UNKNOWN' for e in pos): return f'{n} publications · claim ancestry partly unresolved'
 return f'{n} publication'+('s' if n!=1 else '')
def genealogy(aid):
 rows=[]
 for e in EV.get(aid,[]):
  s=S[e['source_id']]; origin=e.get('claim_origin','UNKNOWN'); parents=e.get('inherits_claim_from_source_ids',[])
  if origin=='ORIGINAL_TO_SOURCE': status='This claim is currently treated as originating in this source.'
  elif origin in {'INHERITED','MIXED'} and parents: status='Draws this claim from: '+', '.join(parents)
  else: status='Where this source got this specific claim has not yet been established.'
  rows.append(f'<li><strong>{esc(s["title"])}</strong><br><span class="small">{esc(status)}</span></li>')
 extra=''
 if aid=='A-0004':
  extra='''<div class="genealogy-note"><strong>Smithsonian research trail still open.</strong><p class="small">The Smithsonian inventory cites Goode (1974), NPS (1985), Michael Richman’s 1967–69 research, and a 1991 Smithsonian research project, but the public catalog does not say which of those supports this specific recast/predecessor claim. Until that mapping is recovered, those references are not counted as independent claim roots.</p><p class="small"><a href="https://github.com/danielastone/dc-public-realm/issues/19">Goode task</a> · <a href="https://github.com/danielastone/dc-public-realm/issues/20">Richman task</a> · <a href="https://github.com/danielastone/dc-public-realm/issues/21">NPS 1985 task</a> · <a href="https://github.com/danielastone/dc-public-realm/issues/22">Smithsonian 1991 task</a></p></div>'''
 return f'<details class="genealogy"><summary>Where this claim comes from</summary><ul>{"".join(rows)}</ul>{extra}<p class="small"><strong>Why this matters:</strong> several publications repeating a statement may still represent one underlying evidence lineage.</p></details>'
def epanel(aid):
 rows=[]
 for e in EV.get(aid,[]):
  s=S[e['source_id']]; note=e.get('evidence_note',''); rows.append(f'<div class="source-row"><strong>{esc(ROLE.get(e["evidence_role"],e["evidence_role"]))}</strong> · {slink(s)}<div class="small">{esc(e.get("locator","Record"))}{" — "+esc(note) if note else ""}</div></div>')
 return f'<details class="evidence"><summary>Evidence for this claim <span>{esc(evidence_label(EV.get(aid,[])))}</span></summary>{"".join(rows)}{genealogy(aid)}<p class="small"><a href="#provenance-{esc(aid)}">View technical provenance</a></p></details>'
def claim(aid,title,text):
 mode=MODE_LABEL.get(MODES.get(aid),'Research claim')
 return f'<article class="claim"><div class="eyebrow">{esc(mode)}</div><h3>{esc(title)}</h3><p>{esc(text)} <a class="cite" href="#provenance-{esc(aid)}">[{esc(aid.replace("A-",""))}]</a></p>{epanel(aid)}</article>'
HOOKS={
'URY-ART-001':('Can you find the diplomatic correspondence?','Uruguay–Washington correspondence from 1947–1951 may identify who authorized, cast, shipped, or described the Washington statue and where later accounts came from.','Find a folder, scan, archival citation, or contact path for the relevant correspondence.'),
'URY-ART-002':('Can you access this 1949 newspaper article?','A pre-dedication El Día article titled “Monumento a Artigas en Washington” may contain contemporary reporting on the statue’s production, financing, shipment, or installation.','Find the complete article, including continuation pages, captions, credits, and page/date metadata.'),
'URY-ART-003':('Can you locate the original Blanes and Costa records?','Uruguay’s 2004 heritage resolution summarizes an 1894 commission and an 1896 Dante Costa contract. We want the underlying records rather than another later summary.','Find an image, catalog record, archival citation, or authoritative reproduction of the 1894 commission or 1896 contract.')
}
def question(t):
 title,plain,quick=HOOKS.get(t['task_id'],(t['title'],t['research_gap'],t['high_value_result']))
 return f'<article class="question"><div class="eyebrow">CAN YOU HELP WITH THIS?</div><h3>{esc(title)}</h3><p>{esc(plain)}</p><p><strong>Smallest useful contribution:</strong> {esc(quick)}</p><a class="button" href="{BASE}/tasks/{esc(t["task_id"].lower())}/">See the research task</a><details><summary>Why this matters</summary><p>{esc(t["research_gap"])}</p></details><details><summary>Research requirements</summary><p class="small"><strong>What would materially advance the record:</strong> {esc(t["high_value_result"])}</p><p class="small"><strong>Evidence rule:</strong> {esc(t["critical_rule"])}</p></details></article>'
LINEAGE_HOOKS=[
('Can you check Goode 1974, pp. 443–444?','These two pages may show which Artigas claims were already in circulation before later NPS and Smithsonian records.','A page scan, transcription of the Artigas entry, or a note of any footnotes/citations.','https://github.com/danielastone/dc-public-realm/issues/19'),
('Can you locate Michael Richman’s 1967–69 Artigas research?','Smithsonian cites this earlier research, but the public inventory does not show which later claims came from it.','A collection/folder citation, finding-aid link, archive contact, or copy of the relevant research notes.','https://github.com/danielastone/dc-public-realm/issues/20'),
('Can you identify the exact NPS 1985 Artigas record?','The Smithsonian inventory cites a 1985 NPS source without exposing its claim-level contribution or upstream references.','An exact title, catalog identifier, scan, or archival location for the cited NPS record.','https://github.com/danielastone/dc-public-realm/issues/21'),
('Can you locate the Smithsonian 1991 Artigas research files?','We need to know whether the 1991 project made independent observations or mainly synthesized earlier publications.','A project-file citation, finding-aid entry, contact path, or description of what the 1991 researchers actually examined.','https://github.com/danielastone/dc-public-realm/issues/22')
]
def lineage_hook(x):
 title,why,quick,url=x
 return f'<article class="question lineage"><div class="eyebrow">TRACE A SOURCE</div><h3>{esc(title)}</h3><p>{esc(why)}</p><p><strong>Smallest useful contribution:</strong> {esc(quick)}</p><a class="button" href="{esc(url)}">Detailed research task</a></article>'
def prov(aid):
 a=A[aid]; rows=[]
 for e in EV.get(aid,[]):
  s=S[e['source_id']]; inh=', '.join(e.get('inherits_claim_from_source_ids',[])) or 'none recorded'; rows.append(f'<li><strong>{esc(e["source_id"])}</strong> — {esc(s["title"])}<br><span class="small">role={esc(e["evidence_role"])} · authority_fit={esc(e.get("authority_fit"))} · proximity={esc(e.get("proximity"))} · claim_origin={esc(e.get("claim_origin"))} · inherited_from={esc(inh)}</span></li>')
 return f'<details class="technical" id="provenance-{esc(aid)}"><summary>{esc(aid)} · {esc(a["predicate"])}</summary><ul>{"".join(rows)}</ul></details>'
roles=[]
for aid,label in [('A-0007A','Commission entrusted to'),('A-0007B','Sketch developed by'),('A-0007C','Modeled and cast by')]:
 obj=E.get(A[aid].get('object_entity_id'),{}).get('canonical_name','Unresolved'); mode=MODE_LABEL.get(MODES.get(aid),'Research claim'); roles.append(f'<li><span class="small">{esc(mode)}</span><br><strong>{esc(label)}:</strong> {esc(obj)}{epanel(aid)}</li>')
sids=[]
for aid in [x[0] for x in CLAIMS]+['A-0007A','A-0007B','A-0007C']:
 for e in EV.get(aid,[]):
  if e['source_id'] not in sids: sids.append(e['source_id'])
source_cards=''.join(f'<li>{slink(S[sid])}<br><span class="small">{esc(S[sid].get("publisher_or_creator",""))} · {esc(S[sid].get("authority_scope",""))}</span></li>' for sid in sids)
css='''<style>:root{--fg:#171717;--muted:#606060;--line:#d9d9d4;--soft:#f7f7f3;--accent:#5a3d16}*{box-sizing:border-box}body{margin:0;color:var(--fg);font-family:ui-serif,Georgia,serif;line-height:1.62}header,main,footer{max-width:900px;margin:auto;padding:1.2rem}header{border-bottom:1px solid var(--line)}nav a{margin-right:1rem;color:inherit}.eyebrow,.small,summary span{font-family:ui-sans-serif,system-ui,sans-serif;color:var(--muted);font-size:.86rem}.eyebrow{letter-spacing:.06em}h1{font-size:clamp(2.3rem,7vw,4.7rem);line-height:1;margin:.3rem 0 1rem}h2{margin-top:3rem;border-bottom:1px solid var(--line);padding-bottom:.35rem}.lede{font-size:1.25rem;max-width:760px}.claim,.question{margin:1.4rem 0}.claim h3,.question h3{margin-bottom:.25rem}.cite{text-decoration:none;font-family:ui-sans-serif,system-ui,sans-serif;font-size:.75rem;vertical-align:super}.evidence,.technical{background:var(--soft);border:1px solid var(--line);padding:.65rem .8rem;margin:.6rem 0}.evidence summary,.technical summary,.genealogy summary{cursor:pointer;font-family:ui-sans-serif,system-ui,sans-serif;font-weight:650}.genealogy{margin:.75rem 0;padding:.6rem .75rem;border-left:3px solid var(--line);background:white}.genealogy li{margin:.55rem 0}.genealogy-note{margin-top:.8rem;padding:.65rem;background:var(--soft)}.evidence summary span{float:right;font-weight:400}.source-row{padding:.6rem 0;border-top:1px solid var(--line)}.source-row:first-of-type{margin-top:.5rem}.question{border-left:4px solid var(--accent);padding:1rem;background:#fffdf8}.question details{margin-top:.75rem}.subhead{margin-top:2.5rem}.question summary{cursor:pointer;font-family:ui-sans-serif,system-ui,sans-serif;font-weight:650}.button{display:inline-block;border:1px solid var(--fg);padding:.45rem .75rem;color:inherit;text-decoration:none}.tabs{position:sticky;top:0;background:white;border-bottom:1px solid var(--line);padding:.7rem 0;z-index:2}.tabs a{margin-right:1rem;font-family:ui-sans-serif,system-ui,sans-serif;font-size:.9rem;color:inherit}.sources li,.technical li{margin:.7rem 0}footer{border-top:1px solid var(--line);margin-top:3rem;color:var(--muted)}@media(max-width:600px){.evidence summary span{float:none;display:block;margin-top:.2rem}.tabs{position:static}}</style>'''
body=f'''<div class="eyebrow">OBJ-0001 · URUGUAY · PUBLICATION PROTOTYPE</div><h1>José Gervasio Artigas Memorial</h1><p class="lede">A diplomatic monument in Washington, D.C., connected to an earlier Artigas monument in San José de Mayo, Uruguay. This page separates what the records document from what later catalogs attribute or leave unresolved.</p><nav class="tabs"><a href="#overview">Overview</a><a href="#evidence">Evidence</a><a href="#sources">Sources</a><a href="#questions">Open questions</a><a href="#provenance">Provenance</a></nav><section id="overview"><h2>Overview</h2><p>U.S. congressional records describe the memorial as a gift from the people of Uruguay. The National Park Service is recorded as its current custodian. Uruguay’s heritage record identifies the Washington bronze as a copy of the 1898 Artigas monument at San José de Mayo; a Smithsonian inventory describes a recast but places the predecessor in Montevideo. The exact physical-object relationship is therefore published as contested rather than normalized away.</p><p>The creative history of the San José monument is more complicated than a single “sculptor” field suggests. Uruguay's heritage resolution records a sequence involving Juan Luis Blanes, Juan Manuel Blanes, and Dante Costa:</p><ul>{''.join(roles)}</ul><p class="small">The evidence currently available for the Washington casting does not identify a foundry. A source failing to identify the founder is not treated as proof that the founder is historically unknowable.</p></section><section id="evidence"><h2>Evidence</h2><p>Claims are presented in ordinary language first. “Historical record” marks documentary propositions; “Attribution” marks authorship, fabrication, or object-lineage reconstructions. These labels describe the kind of scholarly claim, not its confidence. Open an evidence panel to see supporting, qualifying, and contradictory publications and whether their claim ancestry has been established.</p>{''.join(claim(*x) for x in CLAIMS)}</section><section id="sources"><h2>Sources</h2><p>These are sources actually connected to claims on this page. An external institutional record is not automatically evidence for every proposition about the monument.</p><ul class="sources">{source_cards}</ul></section><section id="questions"><h2>Open questions</h2><p>You do not need to understand the database or use GitHub to be useful. A catalog link, page reference, scan location, archive contact, or correction can be enough to move a question forward. Detailed research rules are available only if you want them.</p>{''.join(question(t) for t in tasks)}<h3 class="subhead">Trace the Smithsonian record</h3><p>The Smithsonian Art Inventories entry cites several earlier research streams without mapping individual claims to them. These small source-retrieval tasks test whether later institutional accounts are genuinely independent or inherit the same earlier assertions.</p>{''.join(lineage_hook(x) for x in LINEAGE_HOOKS)}</section><section id="provenance"><h2>Technical provenance</h2><p>This optional layer exposes internal claim and source-lineage metadata used to prevent multiple publications from being mistaken for independent corroboration.</p>{''.join(prov(aid) for aid in [x[0] for x in CLAIMS]+['A-0007A','A-0007B','A-0007C'])}</section>'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>José Gervasio Artigas Memorial | Diplomatic Gifts in Washington</title>{css}</head><body><header><div class="eyebrow">Diplomatic Gifts in Washington · alpha</div><nav><a href="{BASE}/">Home</a><a href="{BASE}/methodology/">Methodology</a><a href="{BASE}/collaborate/">Collaborate</a></nav></header><main>{body}</main><footer>Public presentation is derived from the research graph. Open research leads do not affect claim status until reviewed.</footer></body></html>'''
out=SITE/'objects'/'jose-gervasio-artigas'/'index.html'; out.parent.mkdir(parents=True,exist_ok=True); out.write_text(page,encoding='utf-8'); print('Wrote',out)
